function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    // draw grid
    ctx.strokeStyle='rgba(0,255,255,0.2)';
    for(let i=0;i<=COLS;i++){
      ctx.beginPath();
      ctx.moveTo(i*colW,0);
      ctx.lineTo(i*colW,canvas.height);
      ctx.stroke();
    }
    for(let y=0;y<canvas.height;y+=ROW_H){
      ctx.beginPath();
      ctx.moveTo(0,y);
      ctx.lineTo(canvas.width,y);
      ctx.stroke();
    }
    // draw obstacles
    for(const o of obstacles){
      for(let i=0;i<COLS;i++){
        const cell=o.cells[i];
        if(cell.floor){
          ctx.fillStyle='rgba(0,0,0,0.5)';
          ctx.fillRect(i*colW,o.y,colW,ROW_H);
          if(cell.spike){
            ctx.fillStyle='lime';
            ctx.beginPath();
            ctx.moveTo(i*colW+colW/2, o.y+ROW_H/2-8);
            ctx.lineTo(i*colW+colW/2-8, o.y+ROW_H/2+8);
            ctx.lineTo(i*colW+colW/2+8, o.y+ROW_H/2+8);
            ctx.closePath();
            ctx.fill();
          }
        }
      }
    }
    // draw orb
    ctx.fillStyle='cyan';
    ctx.beginPath();
    ctx.arc(orbCol*colW+colW/2, canvas.height-ROW_H/2, ORB_R,0,2*Math.PI);
    ctx.fill();
  }

